


DROP TABLE IF EXISTS `Monster`;
CREATE TABLE `Monster` (
  `AreaID` int NOT NULL,
  `MonsterID` int NOT NULL,
  `Name` varchar(20) NOT NULL,
  `Model` int NOT NULL,
  `Level` int NOT NULL,
  `MaxHP` int NOT NULL,
  `Experience` int NOT NULL,
  `Defence` int NOT NULL,
  `MDefence` int NOT NULL,
  `bStr` int NOT NULL,
  `bAgi` int NOT NULL,
  `bVit` int NOT NULL,
  `bInt` int NOT NULL,
  `bDex` int NOT NULL,
  `bLuk` int NOT NULL,
  `Element` int NOT NULL,
  `Size` int NOT NULL,
  `MoveSpeed` int NOT NULL,
  `Saliency` int NOT NULL,
  `PopLimit` int NOT NULL,
  PRIMARY KEY (`AreaID`,`MonsterID`)
);

